    { name: 'rewardStage', kind: 'container', position: l.rewardPick.stage.slice(0, 2), size: l.rewardPick.stage.slice(2), visible: false, children: [
      panel('border', 0, 0, ...l.rewardPick.stage.slice(2), c.goldDim),
