  const hex=(name,w,h,colour)=>[
    panel(name,0,0,w-turn.wedge*2,h,colour),
    ...[-1,1].map(side=>({...picture(name+(side<0?'Left':'Right'),side*(w/2-turn.wedge/2),0,h,turn.wedge,100003,colour),rotation:side<0?90:-90})),
