        if (!Array.isArray(list) || list.length !== size) { fail(path, `requires complete ${size}-item source queue`); continue; }
        for (const id of list) {
          if (typeof id !== 'string' || !id || seen.has(id)) fail(path, 'invalid or duplicate source ID');
