  if (errors.length) { console.error(errors.join('\n')); process.exitCode = 1; }
  else console.log('任务编号、首发排期、负责人及旅行者单角色前两幕规划范围检查通过；当前任务均有优先级、未完成High不超过5项；不认证运行时准入、平台或实机。');
}

